steps.prompt:
Read this supplier invoice:
{{brief}}

Answer with JSON only, with these fields: supplier, supplier_tax_id, number, date (YYYY-MM-DD), due (YYYY-MM-DD), currency, net, vat, total (plain numbers with a dot for decimals), iban, lines (a list of {description, amount}). Use null for anything the invoice does not show. Never guess a number.

steps.code:
const f = json(steps[1]) || {}, problems = [], notes = [];
const n = v => v === null || v === undefined || v === '' ? NaN : Number(v);
const net = n(f.net), vat = n(f.vat), total = n(f.total);
if ([net, vat, total].some(Number.isNaN)) problems.push('The net, VAT or total amount could not be read.');
else {
  if (Math.abs(net + vat - total) > 0.02) problems.push('Net ' + net + ' + VAT ' + vat + ' = ' + (net + vat).toFixed(2) + ', but the total says ' + total + '.');
  if (net) notes.push('VAT is ' + (vat / net * 100).toFixed(1) + '% of the net amount.');
}
const lines = Array.isArray(f.lines) ? f.lines : [];
if (lines.length && !Number.isNaN(net)) {
  const sum = lines.reduce((s, l) => s + n(l && l.amount), 0);
  if (Number.isNaN(sum)) problems.push('A line of the invoice has no amount.');
  else if (Math.abs(sum - net) > 0.02) problems.push('The lines add up to ' + sum.toFixed(2) + ', the net amount is ' + net + '.');
}
const iban = String(f.iban || '').replace(/\s/g, '').toUpperCase();
if (iban) {
  let m = 0;
  for (const d of (iban.slice(4) + iban.slice(0, 4)).replace(/[A-Z]/g, c => String(c.charCodeAt(0) - 55))) m = (m * 10 + Number(d)) % 97;
  if (!/^[A-Z]{2}\d{2}[A-Z0-9]{10,30}$/.test(iban) || m !== 1) problems.push('The IBAN ' + iban + ' fails its check digits: confirm it with the supplier before paying.');
} else notes.push('No IBAN on the invoice.');
// A Romanian tax ID (CUI/CIF) has a check digit of its own.
const cui = String(f.supplier_tax_id || '').toUpperCase().replace(/\s/g, '');
if (/^(RO)?\d{2,10}$/.test(cui)) {
  const d = cui.replace('RO', ''), body = d.slice(0, -1).padStart(9, '0'), key = '753217532';
  let s = 0;
  for (let i = 0; i < 9; i++) s += Number(body[i]) * Number(key[i]);
  if (s * 10 % 11 % 10 !== Number(d.slice(-1))) problems.push('The supplier tax ID ' + cui + ' fails its check digit.');
}
const issued = Date.parse(f.date), due = Date.parse(f.due);
if (!Number.isNaN(issued) && !Number.isNaN(due) && due < issued) problems.push('The due date is before the invoice date.');
if (!Number.isNaN(due) && due < Date.now()) notes.push('The due date (' + f.due + ') has passed.');
return (problems.length ? 'PROBLEMS:\n- ' + problems.join('\n- ') : 'CHECKS PASSED') + (notes.length ? '\n\nNotes:\n- ' + notes.join('\n- ') : '');

